package com.tiviloom.mobile;
import android.app.*;import android.content.*;
public final class ReminderReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context c,Intent intent){if(Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction())){ReminderScheduler.restore(c);return;}String key=intent.getStringExtra("key");if(key==null||!ReminderScheduler.prefs(c).getBoolean("enabled",false)||!ReminderScheduler.prefs(c).contains(key))return;ReminderScheduler.prefs(c).edit().remove(key).apply();NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("programmes","Proqram xatırlatmaları",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{manager.notify(key,0,new Notification.Builder(c,"programmes").setSmallIcon(R.drawable.ic_launcher).setContentTitle("TiviLoom · Proqram başlayır").setContentText(intent.getStringExtra("title")).setContentIntent(open).setAutoCancel(true).build());}catch(SecurityException ignored){}}
}
